function createCoolingTower(x, z, scale) {
  const group = new THREE.Group();
  const segments = 32;
  const points = [];
  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    const y = (t * 8 - 2) * scale;
    const width = 1.0 + 1.5 * Math.pow(t - 0.5, 2) * 2;
    points.push(new THREE.Vector2(width * scale * 1.8, y));
  }

  const towerGeo = new THREE.LatheGeometry(points, 48);
  const towerMat = new THREE.MeshStandardMaterial({ color: 0xe8ecf1, roughness: 0.9, metalness: 0.02, side: THREE.DoubleSide });
  const tower = new THREE.Mesh(towerGeo, towerMat);
  tower.castShadow = true;
  tower.receiveShadow = true;
  group.add(tower);

  const topY = 6 * scale;
  const topR = (1.0 + 1.5 * Math.pow(1 - 0.5, 2) * 2) * scale * 1.8;
  const rim = new THREE.Mesh(new THREE.TorusGeometry(topR, 0.15 * scale, 12, 48), concreteMat);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = topY;
  group.add(rim);

  const baseR = (1.0 + 1.5 * Math.pow(0 - 0.5, 2) * 2) * scale * 1.8;
  const skirt = new THREE.Mesh(new THREE.CylinderGeometry(baseR, baseR * 1.1, 1 * scale, 48), concreteMat);
  skirt.position.y = -2 * scale - 0.5 * scale;
  skirt.castShadow = true;
  group.add(skirt);

  group.position.set(x, 0, z);
  return group;
}

