function createCoolingTower(x, z, scale) {
  const group = new THREE.Group();
  const h = 7 * scale;
  const baseR = 2.2 * scale;
  const topR = 1.4 * scale;

  const towerGeo = new THREE.CylinderGeometry(topR, baseR, h, 56, 1, true);
  const towerMat = new THREE.MeshStandardMaterial({ color: 0xe8ecf1, roughness: 0.85, side: THREE.DoubleSide });
  const tower = new THREE.Mesh(towerGeo, towerMat);
  tower.position.y = (h / 2) - 2;
  tower.castShadow = true;
  tower.receiveShadow = true;
  group.add(tower);

  const rimGeo = new THREE.TorusGeometry(topR, 0.12 * scale, 12, 56);
  const rim = new THREE.Mesh(rimGeo, concreteMat);
  rim.rotation.x = Math.PI / 2;
  rim.position.y = h - 2;
  group.add(rim);

  const baseGeo = new THREE.CylinderGeometry(baseR, baseR * 1.1, 1.2 * scale, 56);
  const base = new THREE.Mesh(baseGeo, concreteMat);
  base.position.y = -1.4;
  base.castShadow = true;
  group.add(base);

  group.position.set(x, 0, z);
  return group;
}

