function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  reactorGroup.rotation.y = t * 0.06;

  const pulse = 2.0 + Math.sin(t * 1.8) * 0.6;
  coreMat.emissiveIntensity = pulse;
  coreLight.intensity = pulse * 0.9;

  rodGroup.children.forEach((child) => {
    if (child.userData.id !== undefined) {
      child.position.y = child.userData.baseY + Math.sin(t * 0.4 + child.userData.id * 0.5) * 0.15;
    }
  });

  steamParticles.forEach((p, i) => {
    p.position.y += p.userData.speed;
    const drift = Math.sin(t + p.userData.phase) * 0.3;
    p.position.x = p.userData.baseX + drift;
    p.scale.setScalar(1 + (p.position.y - 6) * 0.15);
    p.material.opacity = Math.max(0, 0.25 - (p.position.y - 6) * 0.03);

    if (p.position.y > 12 || p.material.opacity <= 0) {
      p.position.y = 6;
      p.position.x = 8 + (Math.random() - 0.5) * 3;
      p.position.z = (Math.random() - 0.5) * 10;
      p.userData.baseX = p.position.x;
      p.scale.setScalar(1);
      p.material.opacity = 0.25;
    }
  });

  rimLight.intensity = 0.7 + Math.sin(t * 1.2) * 0.15;
  renderer.render(scene, camera);
}
