function createPipe(points, r) {
  const curve = new THREE.CatmullRomCurve3(points);
  const geo = new THREE.TubeGeometry(curve, 64, r, 16, false);
  const mesh = new THREE.Mesh(geo, pipeMat);
  mesh.castShadow = true;
  const group = new THREE.Group();
  group.add(mesh);

  for (let i = 0; i < points.length; i++) {
    const flange = new THREE.Mesh(new THREE.CylinderGeometry(r * 1.8, r * 1.8, 0.15, 16), steelMat);
    flange.position.copy(points[i]);
    group.add(flange);
  }
  return group;
}

