function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  reactorGroup.rotation.y = t * 0.04;

  const pulse = 2.5 + Math.sin(t * 2.0) * 0.8;
  coreMat.emissiveIntensity = pulse;
  coreLight.intensity = pulse * 0.8;
  glowSprite.material.opacity = 0.4 + Math.sin(t * 2.0) * 0.2;
  glowSprite.scale.setScalar(6 + Math.sin(t * 3) * 0.5);

  rodGroup.children.forEach((child) => {
    if (child.userData.id !== undefined) {
      child.position.y = child.userData.baseY + Math.sin(t * 0.3 + child.userData.id * 0.4) * 0.2;
    }
  });

  steamParticles.forEach((p, i) => {
    p.position.y += p.userData.speed;
    const drift = Math.sin(t * 0.5 + p.userData.phase) * 0.5;
    const spread = (p.position.y - 7) * 0.1;
    p.position.x = p.userData.baseX + drift + Math.sin(t + i) * spread;
    p.position.z = p.userData.baseZ + Math.cos(t + i) * spread;
    const life = (p.position.y - 7) / 8;
    p.scale.setScalar(3 + life * 4);
    p.material.opacity = Math.max(0, 0.12 - life * 0.1);

    if (p.position.y > 15 || p.material.opacity <= 0) {
      p.position.y = 7;
      p.position.x = 9 + (Math.random() - 0.5) * 4;
      p.position.z = (Math.random() - 0.5) * 12;
      p.userData.baseX = p.position.x;
      p.userData.baseZ = p.position.z;
      p.scale.setScalar(1.5);
      p.material.opacity = 0.12;
    }
  });

  rimLight.intensity = 0.8 + Math.sin(t * 0.8) * 0.2;
  renderer.render(scene, camera);
}
